        #![trigger crate::mm::phys::region_frame_addrs(base, (count * spec_page_size()) as int)]
        base % spec_page_size() == 0 && forall|i: int|
            0 <= i < count ==> #[trigger] frames[i]@ == base + i * spec_page_size()
}

} // verus!

